package com.contenthub.domain;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="contents") public class Content {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private String title;@Column(nullable=false,unique=true) private String slug;@Column(columnDefinition="text") private String excerpt;@Column(nullable=false,columnDefinition="text") private String body;private String category;@Column(nullable=false) private String status="DRAFT";private Instant createdAt=Instant.now();protected Content(){}public Content(String t,String s,String e,String b,String c,String st){title=t;slug=s;excerpt=e;body=b;category=c;status=st;}public void update(String t,String s,String e,String b,String c,String st){title=t;slug=s;excerpt=e;body=b;category=c;status=st;}public Long getId(){return id;}public String getTitle(){return title;}public String getSlug(){return slug;}public String getExcerpt(){return excerpt;}public String getBody(){return body;}public String getCategory(){return category;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}}